import { useMemo, useState } from 'react';
import {
  Card,
  Chip,
  ChipGroup,
  CircularProgress,
  Badge,
  Pagination,
  EmptyState,
  Button,
  Stack,
  Text,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'warning' | 'exceeded' | 'archived';

interface ProjectBudget {
  id: string;
  name: string;
  quotaPercent: number;
  status: ProjectStatus;
}

const PROJECTS: ProjectBudget[] = [
  { id: 'p1', name: 'Атлас', quotaPercent: 42, status: 'active' },
  { id: 'p2', name: 'Нептун', quotaPercent: 78, status: 'warning' },
  { id: 'p3', name: 'Орион', quotaPercent: 104, status: 'exceeded' },
  { id: 'p4', name: 'Вектор', quotaPercent: 15, status: 'active' },
  { id: 'p5', name: 'Гринвуд', quotaPercent: 60, status: 'archived' },
  { id: 'p6', name: 'Спектр', quotaPercent: 91, status: 'warning' },
  { id: 'p7', name: 'Пульсар', quotaPercent: 33, status: 'active' },
  { id: 'p8', name: 'Меридиан', quotaPercent: 120, status: 'exceeded' },
  { id: 'p9', name: 'Форум', quotaPercent: 8, status: 'active' },
  { id: 'p10', name: 'Каскад', quotaPercent: 55, status: 'archived' },
  { id: 'p11', name: 'Эхо', quotaPercent: 70, status: 'warning' },
  { id: 'p12', name: 'Портал', quotaPercent: 99, status: 'exceeded' },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'В норме',
  warning: 'Близко к лимиту',
  exceeded: 'Превышена',
  archived: 'Архив',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  warning: 'warning',
  exceeded: 'danger',
  archived: 'neutral',
};

const STATUS_ORDER: ProjectStatus[] = ['active', 'warning', 'exceeded', 'archived'];

const PAGE_SIZE = 5;

export default function ProjectBudgetPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>([]);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses([]);
    setPage(1);
  };

  const filteredProjects = useMemo(() => {
    if (activeStatuses.length === 0) return PROJECTS;
    return PROJECTS.filter((project) => activeStatuses.includes(project.status));
  }, [activeStatuses]);

  const totalPages = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, totalPages);

  const pageItems = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;
    return filteredProjects.slice(start, start + PAGE_SIZE);
  }, [filteredProjects, currentPage]);

  return (
    <Card className="jx-p-6">
      <Stack direction="column" gap="4">
        <Stack direction="column" gap="2">
          <Text as="h2" className="jx-text-lg jx-font-semibold" style={{ color: 'var(--jx-color-text-primary)' }}>
            Расход по проектам
          </Text>
          <ChipGroup>
            {STATUS_ORDER.map((status) => (
              <Chip
                key={status}
                selected={activeStatuses.includes(status)}
                onClick={() => toggleStatus(status)}
                onRemove={activeStatuses.includes(status) ? () => toggleStatus(status) : undefined}
                tone={STATUS_TONE[status]}
              >
                {STATUS_LABEL[status]}
              </Chip>
            ))}
          </ChipGroup>
        </Stack>

        {filteredProjects.length === 0 ? (
          <EmptyState
            title="Ничего не найдено"
            description="По выбранным фильтрам нет проектов с расходами."
            action={
              <Button variant="secondary" onClick={resetFilters}>
                Сбросить фильтры
              </Button>
            }
          />
        ) : (
          <>
            <Stack direction="column" gap="3">
              {pageItems.map((project) => (
                <Card key={project.id} variant="outlined" className="jx-p-4">
                  <Stack direction="row" align="center" justify="space-between" gap="4">
                    <Text className="jx-font-medium" style={{ color: 'var(--jx-color-text-primary)' }}>
                      {project.name}
                    </Text>
                    <Stack direction="row" align="center" gap="4">
                      <CircularProgress
                        value={Math.min(project.quotaPercent, 100)}
                        size="sm"
                        tone={STATUS_TONE[project.status]}
                        label={`${project.quotaPercent}%`}
                      />
                      <Badge tone={STATUS_TONE[project.status]}>
                        {STATUS_LABEL[project.status]}
                      </Badge>
                    </Stack>
                  </Stack>
                </Card>
              ))}
            </Stack>

            {totalPages > 1 && (
              <Pagination
                page={currentPage}
                pageCount={totalPages}
                onPageChange={setPage}
              />
            )}
          </>
        )}
      </Stack>
    </Card>
  );
}

